import numpy as np,json
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
s=json.load(open('/app/output/spec.json'));axes=np.array(s['proprio']['axis']);pts=np.array(s['proprio']['position_m'])
def hand(q,left=True):
 p=np.array([.329,.214 if left else -.214,.097]);js=[10]+list(range(11,15) if left else range(15,19))
 for i in js[::-1]:p=Rotation.from_rotvec(axes[i]*q[i]).apply(p-pts[i])+pts[i]
 return p

def ik(target,left=True,init=None):
 ids=list(range(11,15) if left else range(15,19));q=np.zeros(19);limits=np.array(s['qpos']['range'])[ids]
 def fun(v):
  q[ids]=v;return np.r_[5*(hand(q,left)-target),.015*v]
 z=least_squares(fun,np.zeros(4) if init is None else init,bounds=(limits[:,0]+.001,limits[:,1]-.001));q[ids]=z.x
 return z.x,hand(q,left)
if __name__=='__main__':
 for p in [[.6,.65,.0],[.55,.65,-.1],[.6,.55,.1],[.45,.6,-.1]]:print(p,ik(p))
