from control import *
from kin import *
from estimate import attitude,height
class Tracker:
 def __init__(self,o):
  self.R=attitude(o['imu']['gravity']);self.base=np.array([0.,0.,height(o['proprio']['joint_pos'],o['imu']['gravity'])]);self.prev=np.array(o['imu']['gyro']);self.feetworld=self.base+self.footpos(o)
 def footpos(self,o):
  q=o['proprio']['joint_pos'];return self.R.apply(np.array([fk_point(q,[.0915,.203,-1.065],list(range(5))),fk_point(q,[.0915,-.203,-1.065],list(range(5,10)))]))
 def update(self,o):
  w=np.array(o['imu']['gyro']);self.R=self.R*Rotation.from_rotvec((self.prev+w)*.01);self.prev=w
  down=self.R.apply(o['imu']['gravity']);corr=Rotation.align_vectors([[0,0,-1]],[down])[0];self.R=corr*self.R
  self.base=np.mean(self.feetworld-self.footpos(o),axis=0)
 def hand(self,o,left=True):return self.base+self.R.apply(hand(o['proprio']['joint_pos'],left))
 def info(self,o):return {'base_est':self.base.tolist(),'rpy_est':self.R.as_euler('xyz').tolist(),'left_est':self.hand(o).tolist(),'right_est':self.hand(o,False).tolist()}

def arm_ik(q,target,left=True,torso=True):
 ids=([10] if torso else [])+list(range(11,15) if left else range(15,19));lim=np.array(s['qpos']['range'])[ids];q=np.array(q,float)
 orig=q[ids].copy()
 def fun(v):
  q[ids]=v;return np.r_[10*(hand(q,left)-target),.02*(v-orig)]
 z=least_squares(fun,np.clip(orig,lim[:,0]+.002,lim[:,1]-.002),bounds=(lim[:,0]+.001,lim[:,1]-.001),max_nfev=80);q[ids]=z.x
 return q,np.linalg.norm(hand(q,left)-target)

class Controller:
 def __init__(self):
  self.o=r.observe(False);self.tr=Tracker(self.o)
 def go(self,q,n,target=None,righttarget=None):
  q=np.array(q,float)
  for i in range(n):
   t=q.copy()
   if target is not None and i%5==0:
    local=self.tr.R.inv().apply(np.array(target)-self.tr.base);t,err=arm_ik(self.o['proprio']['joint_pos'],local);q[10:15]=t[10:15]
   t=q.copy()
   if righttarget is not None:
    local=self.tr.R.inv().apply(np.array(righttarget)-self.tr.base);t,err=arm_ik(t,local,False,False)
