   with open('/app/output/actions.jsonl','a') as f:f.write(json.dumps(a.tolist())+'\n')
   with open('/app/output/observations.jsonl','a') as f:f.write(json.dumps({'step':self.o['step'],**self.tr.info(self.o),'proprio':self.o['proprio'],'imu':self.o['imu']})+'\n')
   if self.o['done']:break
  save(r.observe());print(self.tr.info(self.o));return q
